namespace OpenTPW;

/// <summary>
/// The queue slice's approximation register (docs/GUESTS.md, "Queues"; docs/reverse/QUEUE-plan.md §10). Each
/// entry is tagged <c>[APPROX:QUEUE-NNN]</c> at its code site. Everything else in the queue model is traced
/// from the Mac binary (BIN labels at the code sites).
/// </summary>
public static class QueueApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("QUEUE-003", "back-cell admission and fourth-slot path geometry are implemented; supported live typed HasQueue entries derive their front from the actual entry link byte (+0x0C, tp.exe 0x4DE040, bits 1, 16, 64, 4), and a native zero front (no cardinal bit; 0x4DE4A0 reads such a ride as unconnected, which the opening guard still answers permissively under ECON-049) leaves its demolition without a count to undo (0x527FB4) and its re-evaluation without a block stamp; a zero-front ride has back cell 0 and size 0 for the guests (they neither score, choose nor join it, and its queued guests but the called one leave at the re-evaluation) with the host's one-cell geometry kept for the called guest's stand cell and the queue tool; unsupported entries (a neighbour off the map) retain the host positive one-cell fallback (untyped worlds keep it too: the gates and test rigs keep it as [EXT:untyped-harness-world], user-approved 2026-10-30, not part of this ID; a Theme Park Inc layout until RIDES-031 types it); a saved mEntryPos that differs from the placement's access cell is reported and the placement's kept (the constructor 0x004DB090 derives it from the shape); an original save's head, links and called guest (mFirstInQ, mQNext, mQPrev, mPersonBeingLoaded) and its cached back cell and size (+0x3A, +0x40) are imported as read; the native cache invalidation timing (0x4DE130 keeps +0x3A until the next 0x4DE1F0, where OpenTPW recomputes on every grid change) remains unsupported. No corpus or Easymode save holds a guest in states 8/11-15 or a set mFirstInQ; the queue import is checked on synthetic saves only."),
		("QUEUE-010", "a guest leaving a queue (0x5004AA, the queue edit's dismissal 0x501390, a removed ride's message 0x4FB360) stays where it stands in state 6 on every placed ride, whatever its cell is now (a path, a queue cell, the owned stand cell, or a cell the queue's undo or a demolition emptied), and decides from there by the ported wander (0x4F9490); a bridge without placed cells (no owner word or no exit cell: the Theme Park Inc slice until RIDES-031 types it) retains the front/nearest-path relocation, whose cells carry no links to walk off by (the gates and test rigs keep it as [EXT:untyped-harness-world], user-approved 2026-10-30, not part of this ID); the exit of a guest whose attraction is already gone (a safety net: the original has no such poll, only the removal message 0x4FB360) now stays where it stands too"),
		("QUEUE-012", "queue cells follow the decision order of tp.exe's validator 0x00535670 (QueueCellValidator, replayed on all 14,256 answers of the executable's own sweep) for the rides that carry an owner word (every placed Theme Park World ride): the path tool's per-cell route and the queue tool's native reducer ask it for a refusal on top of their own rules, and the cell it reads is the cell's own type, which is what the type byte holds apart from a track tile of the second layer that the byte only shows while the cell is empty (ParkCellMap.PrimaryTypeAt; the validator reads the tile's record apart, so a path or queue cell is laid over a straight or stub tile and the four cells of a corner or junction tile, a hoarding post and the coaster marker 0x15 are refused): the flag 0x40 refuses first, an object's cell (types 4, 9 and 10) is accepted only when its class-3 owner's overwrite priority is below the tool's 3 (0x818C10, 0x535D66; Objects.GivesWay; the priority 0x818C14 is reset to 0 by the hover, 0x523522, set by each class-3 owner and kept by an owner that is none, as the path tool's line walk carries it), a hoarding post and the three cells beside it are refused on owned land as well, an empty cell is accepted and the validator reads no MAP terrain bit; the latches 0x816D50 and 0x816D58 are reset by the hover (0x5234F2, 0x5234F8), by the commit's pass set-up (0x527C52, 0x527C5C) and by the mode change (0x52F11B, 0x52F121), so every pass over a line starts clean and a refusal marks the rest of that pass only, which the path tool's line walk carries and which changes no answer of the queue tool's lines (a refused cell stops them); the native reducer accepts a queue cell only when its owner word is the tool's ride and it holds no two links (0x535670, mode 3 over type 3), so it neither crosses the ride's own two-link cell nor another ride's cell. Residual: the per-cell route of the queue tool for rides without an owner word (the Theme Park Inc slice until RIDES-031 types it) keeps its own rules (it asks the validator's refusals, refuses any queue cell and keeps no latch), and the gates and test rigs keep them too as [EXT:untyped-harness-world] (user-approved 2026-10-30, not part of this ID); a typed world asks the validator alone (the cell's own type, flags and owner; no MAP terrain bit, as 0x535670 reads none), and a Theme Park Inc layout and a read-only visit, whose footprints are untyped until RIDES-031, still ask OpenTPW's terrain rule on top (Objects.Grid.CheckTerrain: the map start's cell types, with the Easymode save's occupied cells before the live map is attached); a path or queue cell laid over or taken off a track tile does not re-test the tile's bridge (TRACK-010)"),
		("QUEUE-015", "the queue tool's undo (Back 0x52FE50) takes cells and refunds as 0x5367A0 does and writes no guest: the re-evaluation that follows (0x4DE1F0 at 0x52FFEC, 0x501390 per guest) dismisses by place alone; the corner walk's counters (+0x20: 1 on a corner, 0 elsewhere, 0x5302C2) are written by the queue edit click, whose tool takes the segments back through the native undo (the cells go from the segment's end, so a corner keeps its counter 1 - 1 and stays); a ride whose front holds no queue cell is demolished with one cell's debit (0x527FB4). The tool entries that run no walk here (a ride's placement, the ride window's button, a track's or coaster's completion) take the chain from the segment's first cell on without counters, and the removal from a clicked cell on stays only as the labelled extensions EXT:dev-one-click-remove and EXT:queue-backtrack, which keep the original's guest policy (the clear writes no guest and the re-evaluation dismisses by place)"),
	};
}
